from django import template
from django.template.base import token_kwargs
from djinn.core.cva import cva

register = template.Library()

toggle_group_cva = cva(
    base="inline-flex items-center justify-center rounded-md border bg-background shadow-sm ring-offset-background",
    variants={
        "variant": {
            "default": "border-input",
            "outline": "border-input",
        },
        "size": {
            "sm": "h-8",
            "default": "h-10",
            "lg": "h-11",
        },
    },
    default_variants={
        "variant": "default",
        "size": "default",
    }
)

class ToggleGroupNode(template.Node):
    def __init__(self, nodelist, kwargs):
        self.nodelist = nodelist
        self.kwargs = kwargs

    def render(self, context):
        resolved_kwargs = {}
        for k, v in self.kwargs.items():
            try:
                resolved_kwargs[k] = v.resolve(context)
            except template.VariableDoesNotExist:
                resolved_kwargs[k] = ""

        final_class = toggle_group_cva(**resolved_kwargs)

        known_args = ["variant", "size", "class", "class_name", "slot"]
        attrs = {k: v for k, v in resolved_kwargs.items() if k not in known_args}

        slot = self.nodelist.render(context) if self.nodelist else ""
        t = context.template.engine.get_template('components/toggle-group.html')
        new_context = context.new({
            "class": final_class,
            "slot": slot,
            "attrs": attrs,
            **resolved_kwargs
        })
        return t.render(new_context)

@register.tag('djinn_toggle_group')
def djinn_toggle_group(parser, token):
    bits = token.split_contents()
    kwargs = token_kwargs(bits[1:], parser)
    nodelist = parser.parse(('enddjinn_toggle_group',))
    parser.delete_first_token()
    return ToggleGroupNode(nodelist, kwargs)
